using System;
using LastRail.Battle;
using LastRail.Run;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
public sealed class OrdinaryGeometryBindingTests {
 [TestCase("same")][TestCase("missing")][TestCase("changed")]
 public void NodeRequiresOriginalStartReferenceAndRestartKeepsOrigin(string variant){var f=OrdinaryNodeStartWireTests.Fixture(Reference());var b=Attach(f.Response);if(variant=="missing")((JObject)f.Response["receipt"]["nodeStart"]["snapshot"]["runtime"]["spatial"]).Remove("definitionBinding");if(variant=="changed")b["definitionRef"]["definitionHash"]=new string('b',64);Pin(f.Response);var node=BRouteCommandResult.Read(200,f.Response.ToString(),f.Command).NodeStart;if(variant!="same"){Assert.Throws<ArgumentException>(()=>node.RequireOriginal(f.Start));return;}Assert.DoesNotThrow(()=>node.RequireOriginal(f.Start));var request=new OrdinaryNodeRestart(node,"geometry-restart",node.EntryMapRevision,1);var response=new JObject{["accepted"]=true,["version"]="ordinary.node-restart.v1.20261028",["requestId"]=request.Key,["accountId"]=node.AccountId,["runId"]=node.RunId,["nodeId"]=node.NodeId,["status"]="RESTARTED",["revision"]=node.EntryMapRevision+1,["generation"]=2,["snapshot"]=node.Capture()["snapshot"],["snapshotHash"]=node.SnapshotHash};var result=request.ReadResponse(response.ToString());Assert.AreEqual(2,result.Generation);Assert.AreSame(Get(node,"GeometryBinding"),Get(result.Start,"GeometryBinding"));Assert.AreEqual(1L,Get(Get(result.Start,"GeometryBinding"),"OriginGeneration"));}
 static JObject Reference()=>new JObject{["definitionId"]="local-fixture-bodies-v1",["version"]="ordinary.native-geometry-definition.v1.20261031",["definitionHash"]=new string('a',64)};
 static object Get(object owner,string property){var p=owner.GetType().GetProperty(property);Assert.NotNull(p,"Missing geometry consumer "+property);return p.GetValue(owner);}
 static void Pin(JObject response){var node=response["receipt"]["nodeStart"];node["snapshotHash"]=BDirectAttackInput.Digest(node["snapshot"]).Substring(7);}
 static JObject Attach(JObject response){var node=response["receipt"]["nodeStart"];var b=new JObject{["version"]="ordinary.node-geometry-binding.v1.20261031",["accountId"]=node["accountId"].DeepClone(),["runId"]=node["runId"].DeepClone(),["nodeId"]=node["nodeId"].DeepClone(),["entryMapRevision"]=node["entryMapRevision"].DeepClone(),["originGeneration"]=1,["definitionRef"]=Reference()};node["snapshot"]["runtime"]["spatial"]["definitionBinding"]=b;Pin(response);return b;}
 [Test] public void StartKeepsOriginalReferenceAndHistoricalAbsence(){var f=FirstPlayableScalingTests.Fixture(staticSource:true);var old=OrdinaryFiveStartInput.Read(f.Start,"a",(string)f.Start["runId"]);Assert.IsNull(Get(old,"GeometryReference"));f.Start["ordinaryGeometryReference"]=Reference();var current=OrdinaryFiveStartInput.Read(f.Start,"a",(string)f.Start["runId"]);var owned=Get(current,"GeometryReference");f.Start["ordinaryGeometryReference"]["definitionHash"]=new string('b',64);Assert.AreEqual(new string('a',64),Get(owned,"DefinitionHash"));Assert.AreNotEqual(old.StartSnapshotHash,current.StartSnapshotHash);}
 [TestCase("null")][TestCase("version")][TestCase("hash")][TestCase("id")][TestCase("extra")]
 public void StartRejectsMalformedReference(string fault){var f=FirstPlayableScalingTests.Fixture(staticSource:true);var r=Reference();switch(fault){case "null":r=null;break;case "version":r["version"]="other";break;case "hash":r["definitionHash"]=new string('A',64);break;case "id":r["definitionId"]="";break;case "extra":r["approved"]=true;break;}f.Start["ordinaryGeometryReference"]=r;Assert.Throws<ArgumentException>(()=>OrdinaryFiveStartInput.Read(f.Start,"a",(string)f.Start["runId"]));}
 [TestCase("accountId")][TestCase("runId")][TestCase("nodeId")][TestCase("entryMapRevision")][TestCase("originGeneration")][TestCase("version")][TestCase("definitionHash")][TestCase("extra")][TestCase("null")]
 public void RehashedForeignBindingIsRejectedAtArrival(string fault){var f=OrdinaryNodeStartWireTests.Fixture();var b=Attach(f.Response);switch(fault){case "entryMapRevision":case "originGeneration":b[fault]=2;break;case "definitionHash":b["definitionRef"][fault]="bad";break;case "extra":b["fallback"]=true;break;case "null":f.Response["receipt"]["nodeStart"]["snapshot"]["runtime"]["spatial"]["definitionBinding"]=null;break;default:b[fault]="foreign";break;}Pin(f.Response);Assert.Throws<ArgumentException>(()=>BRouteCommandResult.Read(200,f.Response.ToString(),f.Command));}
 [Test] public void BoundNodeCannotUpgradeHistoricalStartOrEnableRuntime(){var f=OrdinaryNodeStartWireTests.Fixture();Attach(f.Response);var node=BRouteCommandResult.Read(200,f.Response.ToString(),f.Command).NodeStart;var owned=Get(node,"GeometryBinding");Assert.NotNull(owned);Assert.AreEqual(1L,Get(owned,"OriginGeneration"));Assert.IsFalse(node.CanStart);Assert.Throws<ArgumentException>(()=>node.RequireOriginal(f.Start));var copy=node.Capture();copy["snapshot"]["runtime"]["spatial"]["definitionBinding"]["originGeneration"]=3;Assert.AreEqual(1L,Get(owned,"OriginGeneration"));}
}
